The following example demonstrates how to create a new watch session, and call methods to transfer
data to the watch. Also include event listeners for receiving data from the watch.

It is important to note that this only works if there is a corresponding watchOS app written
in Objective-C / Swift in the Xcode project inside the extensions folder of the Titanium Project.

#### app.js
``` js        
Ti.WatchSession.activateSession();

var win = Ti.UI.createWindow({
    backgroundColor: 'white'
});

var eventsArea = Ti.UI.createTextArea({
  borderWidth: 2,
  borderColor: '#bbb',
  borderRadius: 5,
  color: '#888',
  font: {fontSize:16},
  textAlign: 'left',
  value: 'This is where we listen for events',
  bottom: 10,
  width: 300, height : 140
});

win.add(eventsArea);

var imageView = Ti.UI.createImageView ({
    top: 240,
    width: 80,
    height: 80
});

win.add(imageView);

var statusBtn = Ti.UI.createButton({
    title: 'status me',
    top: 40
});

statusBtn.addEventListener('click', function(e) {
    eventsArea.value += '\nbtn pressed '
    + '\nwatchOS is supported: ' + Ti.WatchSession.isSupported
    + '\nwatch is paired: ' + Ti.WatchSession.isPaired
    + '\nwatchApp is installed: ' + Ti.WatchSession.isWatchAppInstalled
    + '\nwatchComplication is enabled: ' + Ti.WatchSession.isComplicationEnabled
    + '\nwatch is reachable: ' + Ti.WatchSession.isReachable
    + '\nMost recent app context: ' + JSON.stringify(Ti.WatchSession.recentApplicationContext);
})
win.add(statusBtn);

var sendMsgBtn = Ti.UI.createButton({
    title: 'send Message to watch',
    top: 80
});

sendMsgBtn.addEventListener('click', function(e) {
    Ti.WatchSession.sendMessage({
        message: 'Hi',
        from: 'app',
        type: 'message'
    });
});

var sendUserInfoBtn = Ti.UI.createButton({
    title: 'send User Info to watch',
    top: 120
});

sendUserInfoBtn.addEventListener('click', function(e) {
    Ti.WatchSession.transferUserInfo({
        data: 'user info from app',
        created: '2015'
    });
});

var sendAppContextBtn = Ti.UI.createButton({
    title: 'update app context to watch',
    top: 160
});

sendAppContextBtn.addEventListener('click', function(e) {
    Ti.WatchSession.updateApplicationContext({
        status: 'Application Context from app',
        updates: 2
    });
});

var sendFileBtn = Ti.UI.createButton({
    title: 'send File to watch',
    top: 200
});

sendFileBtn.addEventListener('click', function(e) {
    Ti.WatchSession.transferFile({
        fileURL: '/images/default_app_logo.png',
        metaData: {
            data: 'appcelerator logo'
        }
    });
});

Ti.WatchSession.addEventListener('receivemessage', function(e) {
    eventsArea.value += '\nreceivemessage '
    + '\n' + JSON.stringify(e);
});

Ti.WatchSession.addEventListener('receiveuserinfo', function(e) {
    eventsArea.value += '\nreceiveuserinfo '
    + '\n' + JSON.stringify(e);
});

Ti.WatchSession.addEventListener('receivefile', function(e) {
    eventsArea.value += '\nreceivefile ' + '\n' + JSON.stringify(e);
    var cacheFile = e.data.getFile();
    var downloadedFile = Ti.Filesystem.getFile(Ti.Filesystem.applicationDataDirectory, cacheFile.getName());
    downloadedFile.write(e.data);
    imageView.image = downloadedFile;
});

Ti.WatchSession.addEventListener('receiveapplicationcontext', function(e) {
    eventsArea.value += '\nreceiveapplicationcontext '
    + '\n' + JSON.stringify(e);
});

Ti.WatchSession.addEventListener('watchstatechanged', function(e) {
    eventsArea.value += '\nwatchstatechanged '
    + '\n' + JSON.stringify(e);
});

Ti.WatchSession.addEventListener('reachabilitychanged', function(e) {
    eventsArea.value += '\nreachabilitychanged '
    + '\n' + JSON.stringify(e);
});

Ti.WatchSession.addEventListener('finishfiletransfer', function(e) {
    eventsArea.value += '\nfinishfiletransfer '
    + '\n' + JSON.stringify(e);
});

Ti.WatchSession.addEventListener('finishuserinfotransfer', function(e) {
    eventsArea.value += '\nfinishuserinfotransfer '
    + '\n' + JSON.stringify(e);
});
win.add(sendMsgBtn);
win.add(sendUserInfoBtn);
win.add(sendFileBtn);
win.add(sendAppContextBtn);

win.open();
```

This is a basic map example that places a custom annotation on the map, and
listens for click events on the annotation.

In this example, a custom property (`myid`) is added to the annotation object.
While adding custom members to a Titanium object is not generally recommended,
in this case it provides a mechanism for uniquely identifying an annotation. This
can be useful, for example, if the annotations are dynamically generated
and it is not practical to identify them by title.

``` javascript
import Map from 'ti.map';

const window = Ti.UI.createWindow();

const mountainView = Map.createAnnotation({
    latitude: 37.390749,
    longitude: -122.081651,
    title: 'Appcelerator Headquarters',
    subtitle: 'Mountain View, CA',
    pincolor: Map.ANNOTATION_RED,
    myid: 1 // Custom property to uniquely identify this annotation.
});

const mapView = Map.createView({
    mapType: Map.NORMAL_TYPE,
    region: { 
        latitude: 33.74511,
        longitude: -84.38993,
        latitudeDelta: 0.01,
        longitudeDelta: 0.01
    },
    animate: true,
    regionFit: true,
    userLocation: true,
    annotations: [ mountainView ]
});

const circle = Map.createCircle({
    center: {
        latitude: 33.74511,
        longitude: -84.38993
    },
    radius: 1000, // = 1.0 km
    fillColor: '#20FF0000'
});

mapView.addCircle(circle);
window.add(mapView);

mapView.addEventListener('click', event => {
    Ti.API.info('Clicked ' + event.clicksource + ' on ' + event.latitude + ', ' + event.longitude);
});

window.open();
```

This is a map-example which creates marker annotation and clustering of annotations.

The `clusterIdentifier` property and the `clusterstart` event are required in order to enable
clustering. You can control the clustering by defining the `collisionMode` property and
setting special cluster annotations using the `setClusterAnnotation` method on your map
view instance.

``` javascript
import Map from 'ti.map';

const window = Ti.UI.createWindow();
const annotations = [];

for (let i = 0; i < 10; i++) {
    annotations.push(Map.createAnnotation({
        title: 'Appcelerator Inc.',
        subtitle: 'TiRocks!',
        clusterIdentifier: 'abc', // Required for clusters
        collisionMode: Map.ANNOTATION_VIEW_COLLISION_MODE_RECTANGLE,
        showAsMarker: true,
        markerGlyphText: i.toString(),
        markerColor: 'blue',
        markerGlyphColor: 'green',
        markerTitleVisibility: Map.FEATURE_VISIBILITY_VISIBLE,
        markerSubtitleVisibility: Map.FEATURE_VISIBILITY_HIDDEN,
        markerGlyphImage: 'path/to/flag.png',
        markerSelectedGlyphImage: 'path/to/flag-selected.png',
        annotationDisplayPriority: Map.FEATURE_DISPLAY_PRIORITY_DEFAULT_LOW,
        latitude: (Math.random() * 10) + 40,
        longitude: Math.random() * 10,
    }));
}

const mapView = Map.createView({
    annotations: annotations,
    rotateEnabled: true,
    mapType: Map.MUTED_STANDARD_TYPE,
    showsPointsOfInterest: false,
    userLocation: true
});

mapView.addEventListener('clusterstart', event => {
    Ti.API.info('clustering started!');

    const clusterAnnotation = Map.createAnnotation({
        showAsMarker: true,
        markerText: event.memberAnnotations.length.toString(),
        title: 'Cluster Title',
        subtitle: 'Cluster Subtitle',
    });

    mapView.setClusterAnnotation({
        annotation: clusterAnnotation,
        memberAnnotations: event.memberAnnotations
    });
});
window.add(mapView);
window.open();
```

